      {/* SERVICES */}
      <section className="section" id="services">
        <div className="services-page-layout">
          <div className="services-header">
            <RevealText as="h2">Core Consulting Services to Simplify Your Finances</RevealText>
            <Reveal>
              <Link href="/services" className="btn-view-all">View All Services</Link>
            </Reveal>
          </div>

          <div className="services-page-body">
            <div className="services-accordion services-page-list">
              <Stagger className="services-list">
                {homeServices.map((service, index) => {
                  const isOpen = !!openItems[index];
                  return (
                    <StaggerItem className="service-accordion-item" key={service.title}>
                      <div
                        className="service-accordion-header"
                        onClick={() => toggleAccordion(index)}
                      >
                        <h3>
                          [{String(index + 1).padStart(2, '0')}] {service.title}
                        </h3>
                        <button className="toggle-btn" type="button" aria-label={`Toggle ${service.title}`}>
                          {isOpen ? '−' : '+'}
                        </button>
                      </div>
                      <div className={`service-accordion-content${isOpen ? ' active' : ''}`}>
                        <p className="service-description">{service.description}</p>
                        <ServiceCheckpoints
                          items={service.features}
                          active={isOpen}
                          className="service-features service-features--green-checks"
                        />
                        <Link href={service.href} className="btn-explore">
                          Explore Service Details
                          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                            <path d="M5 12h14" />
                            <path d="M13 6l6 6-6 6" />
                          </svg>
                        </Link>
                      </div>
                    </StaggerItem>
                  );
                })}
              </Stagger>
            </div>

            <Reveal className="services-page-image" delay={0.1}>
              <Image
                src="/assets/images/services-consult-support.png"
                alt="Man writing on paper with calculator at wooden table"
                width={567}
                height={815}
              />
            </Reveal>
          </div>
        </div>
      </section>

      {/* WHY TRUST US */}
